{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export function openProjectStore(path) {
  mkdirSync(dirname(path), { recursive: true });
  const database = new DatabaseSync(path);
  database.exec(`
    PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK (length(trim(name)) > 0)
    );
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK (length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);
  `);
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
    database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
  }
  const projectQuery = `SELECT id, name, archived,
    (SELECT COUNT(*) FROM tasks WHERE project_id = projects.id) AS totalCount,
    (SELECT COUNT(*) FROM tasks WHERE project_id = projects.id AND completed = 1) AS completedCount
    FROM projects`;
  const list = database.prepare(`${projectQuery} ORDER BY id`);
  const find = database.prepare(`${projectQuery} WHERE id = ?`);
  const insert = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const updateArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const updateName = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
  const listTasks = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
  const findTask = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? AND id = ?');
  const insertTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
  const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
  const updateTaskTitle = database.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
  const taskRecord = (task) => task && { ...task, completed: Boolean(task.completed) };
  const projectRecord = (project) => project && { ...project, archived: Boolean(project.archived) };

  function requireActiveProject(projectId) {
    const project = find.get(projectId);
    if (!project || project.archived) {
      const error = new Error(project ? 'Archived projects cannot be changed' : 'Project not found');
      error.status = project ? 409 : 404;
      throw error;
    }
  }

  return {
    list: () => list.all().map(projectRecord),
    find: (id) => projectRecord(find.get(id)),
    create(name) {
      const trimmedName = typeof name === 'string' ? name.trim() : '';
      if (!trimmedName) {
        throw new Error('Project name is required');
      }
      return projectRecord(find.get(insert.run(trimmedName).lastInsertRowid));
    },
    setArchived(id, archived) {
      if (typeof archived !== 'boolean') throw new Error('Project archive state must be a boolean');
      updateArchive.run(Number(archived), id);
      return projectRecord(find.get(id));
    },
    rename(id, name) {
      requireActiveProject(id);
      const trimmedName = typeof name === 'string' ? name.trim() : '';
      if (!trimmedName) {
        const error = new Error('Project name is required');
        error.status = 400;
        throw error;
      }
      updateName.run(trimmedName, id);
      return projectRecord(find.get(id));
    },
    listTasks: (projectId) => listTasks.all(projectId).map(taskRecord),
    createTask(projectId, title) {
      requireActiveProject(projectId);
      const trimmedTitle = typeof title === 'string' ? title.trim() : '';
      if (!trimmedTitle) throw new Error('Task title is required');
      const result = insertTask.run(projectId, trimmedTitle);
      return taskRecord(findTask.get(projectId, result.lastInsertRowid));
    },
    setTaskCompletion(projectId, taskId, completed) {
      requireActiveProject(projectId);
      if (typeof completed !== 'boolean') throw new Error('Task completion must be a boolean');
      updateTask.run(Number(completed), projectId, taskId);
      return taskRecord(findTask.get(projectId, taskId));
    },
    renameTask(projectId, taskId, title) {
      requireActiveProject(projectId);
      const trimmedTitle = typeof title === 'string' ? title.trim() : '';
      if (!trimmedTitle) {
        const error = new Error('Task title is required');
        error.status = 400;
        throw error;
      }
      updateTaskTitle.run(trimmedTitle, projectId, taskId);
      return taskRecord(findTask.get(projectId, taskId));
    },
    close: () => database.close(),
  };
}
import { createServer } from 'node:http';
import { readFileSync } from 'node:fs';
import { openProjectStore } from './project-store.js';

const store = openProjectStore(process.env.DB_PATH || 'data/workboard.sqlite');
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/styles.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/styles.css', import.meta.url))]],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 64 * 1024) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

const server = createServer(async (request, response) => {
  try {
    const pathname = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && pathname === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (pathname === '/api/projects') {
      if (request.method === 'GET') return json(response, 200, store.list());
      if (request.method === 'POST') {
        const input = await readJson(request);
        if (typeof input?.name !== 'string' || !input.name.trim()) {
          return json(response, 400, { error: 'Project name is required' });
        }
        return json(response, 201, store.create(input.name));
      }
    }
    const tasksApi = pathname.match(/^\/api\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*))?$/);
    if (tasksApi) {
      const [, projectId, taskId] = tasksApi;
      if (!store.find(projectId)) return json(response, 404, { error: 'Project not found' });
      if (!taskId && request.method === 'GET') {
        return json(response, 200, store.listTasks(projectId));
      }
      if (!taskId && request.method === 'POST') {
        const input = await readJson(request);
        if (typeof input?.title !== 'string' || !input.title.trim()) {
          return json(response, 400, { error: 'Task title is required' });
        }
        return json(response, 201, store.createTask(projectId, input.title));
      }
      if (taskId && request.method === 'PATCH') {
        const input = await readJson(request);
        if (input && Object.hasOwn(input, 'title')) {
          if (Object.hasOwn(input, 'completed')) {
            return json(response, 400, { error: 'Change task title or completion separately' });
          }
          const task = store.renameTask(projectId, taskId, input.title);
          return task
            ? json(response, 200, task)
            : json(response, 404, { error: 'Task not found' });
        }
        if (typeof input?.completed !== 'boolean') {
          return json(response, 400, { error: 'Task completion must be a boolean' });
        }
        const task = store.setTaskCompletion(projectId, taskId, input.completed);
        return task
          ? json(response, 200, task)
          : json(response, 404, { error: 'Task not found' });
      }
    }
    const projectApi = pathname.match(/^\/api\/projects\/([1-9]\d*)$/);
    if (projectApi) {
      if (request.method === 'GET') {
        const project = store.find(projectApi[1]);
        return project
          ? json(response, 200, project)
          : json(response, 404, { error: 'Project not found' });
      }
      if (request.method === 'PATCH') {
        const input = await readJson(request);
        if (input && Object.hasOwn(input, 'name')) {
          if (Object.hasOwn(input, 'archived')) {
            return json(response, 400, { error: 'Change project name or archive state separately' });
          }
          return json(response, 200, store.rename(projectApi[1], input.name));
        }
        if (typeof input?.archived !== 'boolean') {
          return json(response, 400, { error: 'Project archive state must be a boolean' });
        }
        const project = store.setArchived(projectApi[1], input.archived);
        return project
          ? json(response, 200, project)
          : json(response, 404, { error: 'Project not found' });
      }
    }
    if (request.method === 'GET') {
      const asset = assets.get(/^\/projects\/[1-9]\d*$/.test(pathname) ? '/' : pathname);
      if (asset) {
        response.writeHead(200, { 'Content-Type': asset[0] });
        return response.end(asset[1]);
      }
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    json(response, error.status || 500, {
      error: error.status ? error.message : 'Unable to complete the request',
    });
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

function shutdown() {
  server.close(() => {
    store.close();
    process.exit(0);
  });
  server.closeIdleConnections();
}

process.once('SIGINT', shutdown);
process.once('SIGTERM', shutdown);

const app = document.querySelector('#app');

async function api(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Unable to complete the request');
  return body;
}

function showError(container, message) {
  container.textContent = message;
  container.hidden = false;
}

function projectRow(project, onArchiveChange, pending) {
  const row = document.createElement('li');
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
  const open = document.createElement('button');
  open.type = 'button';
  open.textContent = 'Open project';
  open.addEventListener('click', () => {
    window.location.assign(`/projects/${project.id}`);
  });
  const archive = document.createElement('button');
  archive.type = 'button';
  archive.disabled = pending;
  archive.textContent = project.archived ? 'Restore project' : 'Archive project';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    try {
      await onArchiveChange(project);
    } finally {
      archive.disabled = false;
    }
  });
  row.append(name, summary, open, archive);
  return row;
}

async function renderProjects() {
  app.innerHTML = `
    <h1>Workboard</h1>
    <section aria-labelledby="projects-heading">
      <h2 id="projects-heading">Projects</h2>
      <form>
        <label for="project-name">Project name</label>
        <div class="create-controls">
          <input id="project-name" name="name" type="text" autocomplete="off">
          <button type="submit">Create project</button>
        </div>
      </form>
      <p role="alert" hidden></p>
      <div class="project-filter">
        <label for="project-filter">Project filter</label>
        <select id="project-filter">
          <option value="active">Active</option>
          <option value="archived">Archived</option>
        </select>
      </div>
      <ul aria-label="Projects"></ul>
    </section>`;
  const form = app.querySelector('form');
  const input = app.querySelector('input');
  const button = form.querySelector('button');
  const alert = app.querySelector('[role="alert"]');
  const list = app.querySelector('ul');
  const filter = app.querySelector('select');
  let projects = [];
  const pendingArchives = new Set();

  async function changeArchive(project) {
    if (pendingArchives.has(project.id)) return;
    pendingArchives.add(project.id);
    alert.hidden = true;
    try {
      const updated = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, updated);
    } catch (error) {
      showError(alert, error.message);
    } finally {
      pendingArchives.delete(project.id);
      renderList();
    }
  }

  function renderList() {
    list.replaceChildren(...projects
      .filter((project) => project.archived === (filter.value === 'archived'))
      .map((project) => projectRow(project, changeArchive, pendingArchives.has(project.id))));
  }
  filter.addEventListener('change', renderList);
  // Load before accepting writes so a late list response cannot duplicate a new row.
  button.disabled = true;
  try {
    projects = await api('/api/projects');
    renderList();
    button.disabled = false;
  } catch (error) {
    showError(alert, error.message);
  }
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (button.disabled) return;
    alert.hidden = true;
    const name = input.value.trim();
    if (!name) {
      showError(alert, 'Project name is required');
      input.focus();
      return;
    }
    button.disabled = true;
    try {
      const project = await api('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      projects.push(project);
      renderList();
      input.value = '';
      input.focus();
    } catch (error) {
      showError(alert, error.message);
    } finally {
      button.disabled = false;
    }
  });
}

async function renderProject(id) {
  app.innerHTML = '<button type="button">Projects</button><h1></h1><p role="alert" hidden></p>';
  app.querySelector('button').addEventListener('click', () => window.location.assign('/'));
  try {
    const project = await api(`/api/projects/${id}`);
    app.querySelector('h1').textContent = project.name;
    document.title = `${project.name} · Workboard`;
    if (project.archived) {
      const notice = document.createElement('p');
      notice.textContent = 'Archived project';
      app.append(notice);
    }
    renderRename(project);
    await renderTasks(id, project.archived);
  } catch (error) {
    app.querySelector('h1').textContent = 'Project unavailable';
    showError(app.querySelector('[role="alert"]'), error.message);
  }
}

function renderRename(project) {
  const section = document.createElement('section');
  section.setAttribute('aria-label', 'Rename project');
  section.innerHTML = `
    <form>
      <label for="new-project-name">New project name</label>
      <div class="create-controls">
        <input id="new-project-name" name="name" type="text" autocomplete="off">
        <button type="submit">Rename project</button>
      </div>
    </form>
    <p role="alert" hidden></p>`;
  const form = section.querySelector('form');
  const input = section.querySelector('input');
  const button = section.querySelector('button');
  const alert = section.querySelector('[role="alert"]');
  input.value = project.name;
  input.disabled = project.archived;
  button.disabled = project.archived;
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (button.disabled) return;
    alert.hidden = true;
    const name = input.value.trim();
    if (!name) {
      showError(alert, 'Project name is required');
      input.focus();
      return;
    }
    button.disabled = true;
    try {
      const updated = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      project.name = updated.name;
      app.querySelector('h1').textContent = project.name;
      document.title = `${project.name} · Workboard`;
      input.value = project.name;
    } catch (error) {
      showError(alert, error.message);
    } finally {
      button.disabled = project.archived;
    }
  });
  app.append(section);
}

async function renderTasks(projectId, archived) {
  const section = document.createElement('section');
  section.setAttribute('aria-label', 'Tasks');
  section.innerHTML = `
    <form>
      <label for="task-title">Task title</label>
      <div class="create-controls">
        <input id="task-title" name="title" type="text" autocomplete="off">
        <button type="submit" disabled>Create task</button>
      </div>
    </form>
    <p role="alert" hidden></p>
    <div class="task-filter">
      <label for="task-filter">Task filter</label>
      <select id="task-filter">
        <option value="all">All</option>
        <option value="open">Open</option>
        <option value="completed">Completed</option>
      </select>
    </div>
    <ul aria-label="Tasks"></ul>`;
  app.append(section);
  const form = section.querySelector('form');
  const input = section.querySelector('input');
  const button = form.querySelector('button');
  const alert = section.querySelector('[role="alert"]');
  const filter = section.querySelector('select');
  const list = section.querySelector('ul');
  const path = `/api/projects/${projectId}/tasks`;
  let tasks = [];
  const pendingUpdates = new Set();

  async function updateTask(task, changes) {
    pendingUpdates.add(task.id);
    alert.hidden = true;
    try {
      const updated = await api(`${path}/${task.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(changes),
      });
      Object.assign(task, updated);
    } catch (error) {
      showError(alert, error.message);
    } finally {
      pendingUpdates.delete(task.id);
    }
  }

  function renderList() {
    const matching = tasks.filter((task) => filter.value === 'all'
      || (filter.value === 'completed' ? task.completed : !task.completed));
    list.replaceChildren(...matching.map((task) => {
      const row = document.createElement('li');
      row.dataset.testid = 'task-row';
      const title = document.createElement('span');
      title.textContent = task.title;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      const renameForm = document.createElement('form');
      renameForm.className = 'task-rename';
      const renameLabel = document.createElement('label');
      renameLabel.htmlFor = `new-task-title-${task.id}`;
      renameLabel.textContent = 'New task title';
      const renameControls = document.createElement('div');
      renameControls.className = 'create-controls';
      const renameInput = document.createElement('input');
      renameInput.id = renameLabel.htmlFor;
      renameInput.type = 'text';
      renameInput.name = 'title';
      renameInput.autocomplete = 'off';
      renameInput.value = task.title;
      const renameButton = document.createElement('button');
      renameButton.type = 'submit';
      renameButton.textContent = 'Rename task';
      renameControls.append(renameInput, renameButton);
      renameForm.append(renameLabel, renameControls);
      function setDisabled(pending) {
        checkbox.disabled = archived || pending;
        renameInput.disabled = archived || pending;
        renameButton.disabled = archived || pending;
      }
      setDisabled(pendingUpdates.has(task.id));
      checkbox.addEventListener('change', async () => {
        if (archived || pendingUpdates.has(task.id)) return;
        setDisabled(true);
        await updateTask(task, { completed: checkbox.checked });
        checkbox.checked = task.completed;
        setDisabled(false);
        // Refresh filtered or replaced rows; otherwise preserve the focused checkbox.
        if (filter.value !== 'all' || !checkbox.isConnected) renderList();
      });
      renameForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (archived || pendingUpdates.has(task.id)) return;
        alert.hidden = true;
        const newTitle = renameInput.value.trim();
        if (!newTitle) {
          showError(alert, 'Task title is required');
          renameInput.focus();
          return;
        }
        setDisabled(true);
        await updateTask(task, { title: newTitle });
        title.textContent = task.title;
        checkbox.setAttribute('aria-label', `Complete ${task.title}`);
        renameInput.value = task.title;
        setDisabled(false);
        if (!row.isConnected) renderList();
      });
      row.append(title, checkbox, renameForm);
      return row;
    }));
  }

  filter.addEventListener('change', renderList);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (button.disabled) return;
    alert.hidden = true;
    const title = input.value.trim();
    if (!title) {
      showError(alert, 'Task title is required');
      input.focus();
      return;
    }
    button.disabled = true;
    try {
      tasks.push(await api(path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      }));
      renderList();
      input.value = '';
      input.focus();
    } catch (error) {
      showError(alert, error.message);
    } finally {
      button.disabled = archived;
    }
  });
  try {
    tasks = await api(path);
    renderList();
    button.disabled = archived;
  } catch (error) {
    showError(alert, error.message);
  }
}

const projectPath = window.location.pathname.match(/^\/projects\/([1-9]\d*)$/);
try {
  if (projectPath) await renderProject(projectPath[1]);
  else await renderProjects();
} finally {
  app.setAttribute('aria-busy', 'false');
}
<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Workboard</title>
    <link rel="stylesheet" href="/styles.css">
    <script type="module" src="/app.js"></script>
  </head>
  <body>
    <main id="app" aria-busy="true"></main>
  </body>
</html>
:root {
  font-family: system-ui, sans-serif;
  color: #1d2939;
  background: #f5f7fa;
  line-height: 1.5;
}
* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 0 24px; }
h1 { font-size: 2.25rem; margin: 0 0 28px; }
h2 { font-size: 1.25rem; margin: 0 0 20px; }
section { background: white; border: 1px solid #d6dce5; border-radius: 12px; padding: 24px; }
section + section { margin-top: 24px; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.create-controls { display: flex; gap: 12px; }
input[type="text"], select { min-width: 0; flex: 1; padding: 10px 12px; border: 1px solid #8793a4; border-radius: 6px; font: inherit; }
input[type="checkbox"] { width: 20px; height: 20px; flex-shrink: 0; cursor: pointer; }
.task-filter, .project-filter { margin-top: 24px; }
button { background: #254db0; color: white; border: 0; border-radius: 6px; padding: 10px 16px; font: inherit; cursor: pointer; }
button:hover { background: #193a8d; }
button:disabled, input:disabled { opacity: .6; cursor: not-allowed; }
:focus-visible { outline: 3px solid #c77900; outline-offset: 3px; }
ul { list-style: none; padding: 0; margin: 24px 0 0; }
li { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 0; border-top: 1px solid #d6dce5; }
li span { overflow-wrap: anywhere; min-width: 0; }
